@Service
public class ReportService {
    @Autowired
    private ReportRepository repository;

    public Report generate(Long id) {
        return repository.findEnrichedReport(id);
    }
}

// Plain unit test, no Spring context started:
ReportService service = new ReportService();
service.generate(1L); // NullPointerException -- repository was never injected!

// Constructor injection -- the same class, testable with plain `new`
